// FeedbackCell stores the interrupt budget
class FeedbackCell : public TorqueGeneratedFeedbackCell<FeedbackCell, Struct> {
 public:
  inline void clear_interrupt_budget();
  inline void set_interrupt_budget(int32_t budget);
  inline int32_t interrupt_budget() const;

  // The budget is decremented during bytecode execution
  // When it reaches 0 or goes negative, an interrupt is triggered
  // which calls TieringManager::OnInterruptTick
};

// FeedbackVector tracks IC changes that affect tiering
class FeedbackVector : public TorqueGeneratedFeedbackVector<FeedbackVector, HeapObject> {
 public:
  inline bool interrupt_budget_reset_by_ic_change() const;
  inline void set_interrupt_budget_reset_by_ic_change(bool value);

  // When ICs change, the interrupt budget may be reset to delay optimization
  // until the function stabilizes
  void TieringManager::NotifyICChanged(Tagged<FeedbackVector> vector) {
    // Resets interrupt budget if ICs have changed recently
    // to allow more invocations before optimizing
    if (new_budget > current_budget) {
      vector->set_interrupt_budget_reset_by_ic_change(true);
      cell->set_interrupt_budget(new_budget);
    }
  }
};
